/* eslint-disable @typescript-eslint/no-explicit-any */
import './jest-setup.js';
import { NextRequest } from 'next/server';
import { GET, PUT } from '../user/profile/route';
import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

// Mock console.error to prevent noise in tests
const mockConsoleError = jest.spyOn(console, 'error').mockImplementation(() => {});

// Mock dependencies
jest.mock('next-auth/next');
jest.mock('@/lib/prisma');
jest.mock('@/lib/auth', () => ({
  authOptions: {
    providers: [],
  },
}));

const mockAuth = auth as jest.MockedFunction<any>;

// Get the mocked prisma instance - using any for complex mocks
const mockPrisma = prisma as any;

// Add proper typing for mock functions
const mockFindUnique = mockPrisma.user.findUnique as jest.MockedFunction<any>;
const mockUpdate = mockPrisma.user.update as jest.MockedFunction<any>;

describe('User Profile API', () => {
  const mockSession = {
    user: {
      id: 'user-123',
      name: 'Test User',
      email: 'test@example.com',
    },
  };

  const mockUser = {
    id: 'user-123',
    name: 'Test User',
    email: 'test@example.com',
    image: null,
    createdAt: new Date(),
    dailyCalorieGoal: 2000,
    dailyProteinGoal: 150,
    dailyCarbGoal: 200,
    dailyFatGoal: 70,
    weightUnit: 'kg',
    heightUnit: 'cm',
  };

  beforeEach(() => {
    jest.clearAllMocks();
    mockConsoleError.mockClear();
  });

  afterAll(() => {
    mockConsoleError.mockRestore();
  });

  describe('GET /api/user/profile', () => {
    it('should return 401 when user is not authenticated', async () => {
      mockAuth.mockResolvedValue(null);

      const response = await GET();
      const data = await response.json();

      expect(response.status).toBe(401);
      expect(data.error).toBe('Unauthorized');
    });

    it('should return user profile for authenticated user', async () => {
      mockAuth.mockResolvedValue(mockSession);
      mockFindUnique.mockResolvedValue(mockUser);

      const response = await GET();
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data).toEqual(mockUser);
      expect(mockPrisma.user.findUnique).toHaveBeenCalledWith({
        where: { id: 'user-123' },
        select: {
          id: true,
          name: true,
          email: true,
          image: true,
          createdAt: true,
          dailyCalorieGoal: true,
          dailyProteinGoal: true,
          dailyCarbGoal: true,
          dailyFatGoal: true,
          weightUnit: true,
          heightUnit: true,
        },
      });
    });

    it('should return 404 when user not found', async () => {
      mockAuth.mockResolvedValue(mockSession);
      mockFindUnique.mockResolvedValue(null);

      const response = await GET();
      const data = await response.json();

      expect(response.status).toBe(404);
      expect(data.error).toBe('User not found');
    });

    it('should handle database errors', async () => {
      mockAuth.mockResolvedValue(mockSession);
      mockFindUnique.mockRejectedValue(new Error('Database error'));

      const response = await GET();
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.error).toBe('Internal server error');
    });
  });

  describe('PUT /api/user/profile', () => {
    const updateData = {
      dailyCalorieGoal: 2200,
      dailyProteinGoal: 160,
      dailyCarbGoal: 220,
      dailyFatGoal: 75,
      weightUnit: 'lbs',
      heightUnit: 'ft',
    };

    it('should return 401 when user is not authenticated', async () => {
      mockAuth.mockResolvedValue(null);

      const request = new NextRequest('http://localhost:3000/api/user/profile', {
        method: 'PUT',
        body: JSON.stringify(updateData),
      });
      const response = await PUT(request);
      const data = await response.json();

      expect(response.status).toBe(401);
      expect(data.error).toBe('Unauthorized');
    });

    it('should update user profile successfully', async () => {
      mockAuth.mockResolvedValue(mockSession);
      const updatedUser = { ...mockUser, ...updateData };
      mockUpdate.mockResolvedValue(updatedUser);

      const request = new NextRequest('http://localhost:3000/api/user/profile', {
        method: 'PUT',
        body: JSON.stringify(updateData),
      });
      const response = await PUT(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data).toEqual(updatedUser);
      expect(mockPrisma.user.update).toHaveBeenCalledWith({
        where: { id: 'user-123' },
        data: updateData,
        select: {
          id: true,
          name: true,
          email: true,
          image: true,
          createdAt: true,
          dailyCalorieGoal: true,
          dailyProteinGoal: true,
          dailyCarbGoal: true,
          dailyFatGoal: true,
          weightUnit: true,
          heightUnit: true,
        },
      });
    });

    it('should handle database errors during update', async () => {
      mockAuth.mockResolvedValue(mockSession);
      mockUpdate.mockRejectedValue(new Error('Database error'));

      const request = new NextRequest('http://localhost:3000/api/user/profile', {
        method: 'PUT',
        body: JSON.stringify(updateData),
      });
      const response = await PUT(request);
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.error).toBe('Internal server error');
    });

    it('should handle partial updates', async () => {
      mockAuth.mockResolvedValue(mockSession);
      const partialUpdate = { dailyCalorieGoal: 2500 };
      const updatedUser = { ...mockUser, ...partialUpdate };
      mockUpdate.mockResolvedValue(updatedUser);

      const request = new NextRequest('http://localhost:3000/api/user/profile', {
        method: 'PUT',
        body: JSON.stringify(partialUpdate),
      });
      const response = await PUT(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.dailyCalorieGoal).toBe(2500);
      expect(mockPrisma.user.update).toHaveBeenCalledWith({
        where: { id: 'user-123' },
        data: partialUpdate,
        select: expect.any(Object),
      });
    });
  });
});
